def segs_parallel(A,col):
    h,w=A.shape; pts=set(map(tuple,np.argwhere(A==col))); comps=[]
    # each point belongs to diagonal chain neighbors (+1,-1),(-1,+1)
    while pts:
      seed=next(iter(pts)); q=[seed]; pts.remove(seed); comp=[]
      for r,c in q:
        comp.append((r,c))
        for nr,nc in [(r-1,c+1),(r+1,c-1)]:
          if (nr,nc) in pts: pts.remove((nr,nc));q.append((nr,nc))
      comps.append(sorted(comp))
    return sorted(comps,key=lambda cp:(cp[0][0]+cp[0][1],cp[0][0],cp[0][1]))
